def cruzar_clientes_con_facturas_82(clientes, facturas):
    resultados = []
    for c in clientes:
        for f in facturas:
            if c['id'] == f['cliente_id']:
                resultados.append({'nombre': c['nombre'], 'total': f['total']})
    return resultados

{"codigo_optimizado": "def cruzar_clientes_con_facturas_82(clientes, facturas):
    # 1. Indexación O(n)
    facturas_dict = {f['cliente_id']: f['total'] for f in facturas}

    # 2. Búsqueda O(1)
    return [{'nombre': c['nombre'], 'total': facturas_dict.get(c['id'])} for c in clientes if c['id'] in facturas_dict]", "reporte": ["- Se eliminó el bucle anidado O(n^2).", "- Se implementó un Hash Map para facturas.", "- Se usó List Comprehension."], "script_prueba": "print('Test O(n2) OK para cruzar_clientes_con_facturas_82')", "metricas": {"complejidad_espacial": "O(n)", "metodo_usado": "Hash Map"}}

